<script setup>
import { splitDecisionHistory } from './utils/decision-history.js';
import { statusSummary } from '../shared/status-summary.js';
const state = ref(null);
const email = ref(''); const password = ref(''); const message = ref('');
const editingBrief = ref(false); const contextPreview = ref(null); const codingReview = ref(null);
const brief = reactive({ id: '', name: '', objective: '', text: '' });
const observation = reactive({ requestId: '', sessionId: '', sessionUrl: '', execution: 'exited', observedAt: '', markerVerified: false });
const continuationReview = ref(null);
const notice = ref('');
const showPanel = id => nextTick(() => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
const pilotReview = ref(null); const editingAllowance = ref(false);
const allowance = reactive({ dollars: 1, attempts: 50 });
const note = ref(''); const noteKind = ref('note'); const assignmentOpen = ref(false);
const assignment = reactive({ requestId: '', fromRequestId: undefined, objective: '', acceptance: '', paths: '' });
const resultLabels = { tested_draft_pr: 'Draft PR ready · checks passed', merged_pr: 'PR merged', needs_review: 'PR needs review', branch_without_pr: 'Branch pushed · waiting for a PR', not_found: 'No GitHub result yet', conflicting_prs: 'Multiple matching PRs need review' };
const jobStatus = job => job.releasedAt ? 'Coding run closed' : ['rejected', 'usage_limited'].includes(job.dispatch) ? 'Claude could not start' : job.execution === 'running' ? 'Claude is working' : ['exited', 'stopped'].includes(job.execution) ? 'Claude finished · close this run' : job.dispatch === 'accepted' ? 'Sent to Claude · awaiting progress' : 'Start unconfirmed · check Claude before trying anything else';
function editAllowance() { allowance.dollars = state.value.budgetMicros / 1e6; allowance.attempts = Math.max(50, state.value.maxProviderAttempts); editingAllowance.value = true; pilotReview.value = null; showPanel('pilot-allowance'); }
async function reviewAllowance() { await action(async () => { pilotReview.value = await api('steward/pilot/review', { budgetMicros: Math.round(Number(allowance.dollars) * 1e6), maxProviderAttempts: Number(allowance.attempts) }); }); }
async function approveAllowance() { await action(async () => { await api('steward/pilot/approve', { reviewHash: pilotReview.value.reviewHash }); editingAllowance.value = false; pilotReview.value = null; await refresh(); notice.value = 'Pilot allowance saved. Previous usage is retained. Eve can use your durable project progress with future questions.'; }); }
async function saveNote() { await action(async () => { await api('steward/memory/note', { text: note.value, kind: noteKind.value, expectedContextRevision: state.value.project.revision }); note.value = ''; await refresh(); notice.value = 'Project note saved. Eve will use it with future requests.'; }); }
async function complete(item) { await action(async () => { await api('steward/commitment/complete', { commitmentId: item.id, expectedContextRevision: state.value.project.revision }); await refresh(); notice.value = 'Marked complete as your report. Saved in project progress.'; }); }
function draftAssignment(record) { assignmentOpen.value = true; assignment.requestId = crypto.randomUUID(); assignment.fromRequestId = record?.id; assignment.objective = record?.proposal?.title || ''; assignment.acceptance = record?.proposal?.rationale || ''; assignment.paths = ''; showPanel('assignment'); }
async function prepareAssignment() { await action(async () => { codingReview.value = await api('steward/coding/prepare', { requestId: assignment.requestId, fromRequestId: assignment.fromRequestId, objective: assignment.objective, acceptance: assignment.acceptance, allowedPaths: assignment.paths.split(/\n/).map(p => p.trim()).filter(Boolean), expectedContextRevision: state.value.project.revision }); assignmentOpen.value = false; await refresh(); showPanel('coding-review'); notice.value = 'Assignment prepared against the current GitHub base. Review its exact scope before starting Claude.'; }); }
async function checkGitHub(job) { await action(async () => { await api('steward/coding/reconcile', { requestId: job.id }); await refresh(); notice.value = 'GitHub progress checked and saved.'; }); }
let refreshTimer;
onUnmounted(() => clearInterval(refreshTimer));
async function reviewContinuation() { await action(async () => { continuationReview.value = await api('steward/continuation/review', {}); }); }
async function continuePilot() { await action(async () => { await api('steward/continuation/approve', { reviewHash: continuationReview.value.reviewHash }); continuationReview.value = null; notice.value = 'One more Eve request is approved. Nothing has been sent yet.'; message.value = 'Using the verified coding result, propose the next owner decision. Distinguish the completed draft PR from a merge or deployment. Do not repeat the completed coding assignment.'; await refresh(); }); }
const busy = ref(false); const error = ref(''); const checking = ref(true);
const dollars = value => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 3 }).format(value / 1e6);
const labels = { assignment_prepared: 'Assignment prepared below for review', not_sent: 'Not sent · check allowance or brief size', thinking: 'Waiting for Eve', held: 'Needs operator review', resolved_rejection: 'Recovered; original attempt retained', rejection_acknowledged: 'Failed review acknowledged · history kept', awaiting_approval: 'Your decision', approved: 'Committed', needs_context: 'Needs your context', coding_dispatched: 'Coding handoff recorded' };
const errors = { RECOVERY_REVIEW_STALE: 'This recovery view is out of date. Refresh status and read the updated handoff.', RECOVERY_NOT_SUPPORTED: 'This held attempt cannot be acknowledged here. Follow the handoff shown on it.', RECOVERY_TASK_ACTIVE: 'The coding task has not stopped yet. Wait for follow-through to stop it, then refresh.', PILOT_REVIEW_STALE: 'The allowance review expired or changed. Review it again.', PILOT_SETTINGS_INVALID: 'Use a total cap between the already-reserved amount and $10, and 1–250 total attempts.', INVALID_REQUEST: 'Check the form. Coding scope needs 1–10 exact file paths, one per line.',  CONTINUATION_CONTEXT_CHANGED: 'The brief changed after the follow-up was approved. Ask the operator for a new scoped review.', CONTINUATION_UNAVAILABLE: 'Finish and close the coding run before reviewing continuation. This one-request extension may already be used.', CONTINUATION_REVIEW_STALE: 'The review expired or the work changed. Review continuation again.', CONTINUATION_SOURCE_EXPIRED: 'The reviewed coding result has expired. Ask the operator to refresh the context before continuing.', RETRY_REVIEW_MISMATCH: 'This failed request has changed or was already retried. Refresh its status.', RETRY_NOT_READY: 'The provider asked us to wait longer before retrying.', UNRESOLVED_MODEL_ATTEMPT: 'A prior request needs review before another can run.', CONTEXT_EXPIRED: 'The project brief has expired. Refresh it with the operator before asking Eve.', ADMISSION_PAUSED: 'New requests are paused.', APPROVAL_MISMATCH: 'This proposal no longer matches the current brief. Refresh to review the latest state.', CODING_NOT_ENABLED: 'Coding dispatch is not connected or its verification has expired.', CONTEXT_PREVIEW_STALE: 'This preview expired or the brief changed. Preview again.', CONTEXT_WORK_UNRESOLVED: 'Resolve the active or uncertain work before changing the project brief.', CODING_PREFLIGHT_FAILED: 'Repository verification failed. No coding dispatch was sent.', CODING_ADMISSION_PAUSED: 'Coding admission is paused or another job occupies the slot.', CODING_RELEASE_UNVERIFIED: 'Record the provider session ending, then refresh its evidence before releasing the slot.' };
async function api(path, body) {
  const response = await fetch(`/api/${path}`, { method: body === undefined ? 'GET' : 'POST', credentials: 'same-origin', headers: body === undefined ? {} : { 'content-type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body) });
  const data = await response.json();
  if (!response.ok) { if (response.status === 401) state.value = null; throw new Error(errors[data.error] || (response.status === 401 ? 'Sign in to continue.' : 'This action could not be completed. Refresh to check its status.')); }
  return data;
}
async function refresh() { state.value = await api('steward/state'); }
async function action(fn) { busy.value = true; error.value = ''; notice.value = ''; try { await fn(); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function login() { await action(async () => { try { await api('auth/sign-in/email', { email: email.value, password: password.value }); await refresh(); } finally { password.value = ''; } }); }
async function propose() { await action(async () => { notice.value = 'Eve is considering your request. This can take about a minute.'; const result = await api('steward/propose', { requestId: crypto.randomUUID(), projectId: state.value.project.id, expectedContextRevision: state.value.project.revision, message: message.value }); message.value = ''; await refresh(); notice.value = result.proposal ? `Eve replied: ${result.proposal.title}. See the newest decision below.` : 'Your request is saved, but Eve did not return a verified result. See the latest decision.'; document.getElementById('decisions')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }); }
async function retryRejected(record) { await action(async () => { await api('steward/propose', { requestId: crypto.randomUUID(), projectId: record.projectId, message: record.message, expectedContextRevision: record.contextRevision, retryOf: record.id, rejectionHash: record.retryReviewHash }); await refresh(); }); }
const caseLabels = { confirmed_rejection: 'Confirmed provider refusal', uncertain_delivery: 'Delivery outcome unknown', unverified_output: 'Output not verified', expired_authority: 'Provider refusal · authority expired', allowance_exhausted: 'Provider refusal · allowance exhausted', unclassified: 'Cannot be classified safely' };
const micros = value => `$${(value / 1e6).toFixed(6).replace(/0+$/, '').replace(/\.$/, '')}`;
async function acknowledgeRecovery(record) { await action(async () => { await api('steward/recovery/acknowledge', { requestId: record.id, acknowledgeHash: record.recovery.acknowledgeHash }); await refresh(); notice.value = 'Failed review acknowledged. Its history and reservation are kept; nothing was retried or resumed.'; }); }
function startFresh() { showPanel('request'); nextTick(() => document.getElementById('request')?.focus()); }
const retryBlocked = record => busy.value || state.value.paused || !state.value.contextFresh || state.value.providerAttempts >= state.value.maxProviderAttempts || record.contextRevision !== state.value.project.revision || state.value.requests.some(r => r.id !== record.id && ['thinking', 'held'].includes(r.status));
async function approve(record) { await action(async () => { await api('steward/approve', { requestId: record.id, proposalHash: record.proposalHash }); await refresh(); }); }
function editBrief() { editingBrief.value = true; contextPreview.value = null; Object.assign(brief, { id: state.value.project.id, name: state.value.project.name, objective: state.value.project.objective, text: state.value.project.sources.map(s => s.content).join('\n\n') }); }
async function loadBrief(event) { const file = event.target.files?.[0]; if (!file) return; if (file.size > 16000 || !/\.(md|txt)$/i.test(file.name)) { error.value = 'Choose a Markdown or text file up to 16 KB.'; return; } const text = await file.text(); if (text.length > 4000) { error.value = 'Keep the brief under 4,000 characters.'; return; } brief.text = text; contextPreview.value = null; }
async function previewBrief() { await action(async () => { const at = new Date(); contextPreview.value = await api('steward/context/preview', { project: { id: brief.id, name: brief.name, objective: brief.objective, sources: [{ id: 'brief', title: 'Owner-approved project brief', revision: at.toISOString(), observedAt: at.toISOString(), expiresAt: new Date(at.getTime() + 7 * 86400000).toISOString(), content: brief.text, exposure: 'model_allowed' }], codingCandidates: [] } }); }); }
async function applyBrief() { await action(async () => { await api('steward/context/apply', { previewId: contextPreview.value.id, expectedRevision: contextPreview.value.expectedRevision }); contextPreview.value = null; editingBrief.value = false; codingReview.value = null; await refresh(); }); }
async function reviewCoding(record) { await action(async () => { codingReview.value = await api('steward/coding/review', { requestId: record.id, proposalHash: record.proposalHash }); showPanel('coding-review'); }); }
async function dispatchCoding() { await action(async () => { const r = codingReview.value; const job = await api('steward/coding/approve', { requestId: r.requestId, proposalHash: r.proposalHash, reviewHash: r.reviewHash }); codingReview.value = null; await refresh(); notice.value = jobStatus(job); }); }
function observeJob(job) { Object.assign(observation, { requestId: job.id, sessionId: job.session?.id || '', sessionUrl: job.session?.url || job.receipt?.sessionUrlHint || '', execution: 'exited', observedAt: new Date().toISOString(), markerVerified: false }); }
async function saveObservation() { await action(async () => { const match = observation.sessionUrl.match(/^https:\/\/claude\.ai\/code\/(session_[A-Za-z0-9_-]+)$/); if (!match) throw new Error('Paste the Claude session link shown in your browser.'); await api('steward/coding/close', { ...observation, sessionId: match[1] }); observation.requestId = ''; await refresh(); notice.value = 'Claude completion saved, GitHub checked, and coding run closed. Eve will retain the result.'; }); }
async function signOut() { await action(async () => { await api('auth/sign-out', {}); state.value = null; message.value = ''; contextPreview.value = null; codingReview.value = null; continuationReview.value = null; notice.value = ''; editingBrief.value = false; brief.text = ''; }); }
onMounted(async () => { try { await refresh(); } catch { /* Show the owner login without leaking setup details. */ } finally { checking.value = false; } refreshTimer = setInterval(() => { if (state.value && (busy.value || state.value.requests.some(r => r.status === 'thinking') || state.value.codingJobs.some(j => !j.releasedAt))) refresh().catch(() => {}); }, 5000); });
const decisionGroups = computed(() => {
  const { current, historical } = splitDecisionHistory(state.value?.requests, state.value?.project?.revision);
  return [
    { key: 'current', heading: 'Current project', note: 'Decisions made under the approved brief you are working from now.', empty: 'No decisions yet for the current brief. Your next question starts its loop; earlier decisions stay below for reference.', records: current },
    { key: 'historical', heading: 'Earlier projects', note: 'Recorded under a previous brief. These stay inspectable but cannot be approved for the current brief.', empty: '', records: historical },
  ].filter(group => group.records.length || group.key === 'current');
});
const summary = computed(() => (state.value ? statusSummary(state.value) : ''));
const blocked = computed(() => state.value?.continuationProblem || state.value?.paused || state.value?.providerAttempts >= state.value?.maxProviderAttempts || !state.value?.contextFresh || state.value?.requests.some(r => ['thinking', 'held'].includes(r.status)));
</script>
<template>
  <main>
    <header><a class="brand" href="/">S<span>Project Steward</span></a><button v-if="state" class="quiet" :disabled="busy" @click="signOut">Sign out</button><span v-else class="tag">PRIVATE ALPHA</span></header>
    <div v-if="checking" class="loading" role="status">Opening your workspace…</div>
    <section v-else-if="!state" class="login">
      <p class="eyebrow">ONE PROJECT. THE NEXT USEFUL STEP.</p>
      <h1>Keep the work<br>moving.</h1>
      <p class="intro">Your project’s current context, considered decisions, and commitments in one place.</p>
      <form @submit.prevent="login"><label>Email<input v-model="email" type="email" autocomplete="username" required></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required></label><button :disabled="busy">{{ busy ? 'Signing in…' : 'Open my workspace' }}</button></form>
      <p class="muted">Owner access only. Account creation is managed separately.</p>
    </section>
    <template v-else>
      <section class="heading"><p class="eyebrow">YOUR WORKSPACE</p><h1>{{ state.project.name }}</h1><p class="intro">{{ state.project.objective }}</p><div class="meta"><span class="tag" :class="{ warning: !state.contextFresh }">{{ state.contextFresh ? 'Context current' : 'Context expired' }}</span><span>Eve · {{ state.judge }}</span></div><p class="summary">{{ summary }}</p></section>
      <p v-if="notice" role="status" class="notice feedback">{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p>
      <section id="pilot-allowance" v-if="editingAllowance" class="card"><h2>Pilot allowance</h2><p>Set cumulative limits for Eve’s model requests. Previous reservations and attempts stay counted. Claude coding continues to use the existing subscription with paid overage disabled.</p><form @submit.prevent="reviewAllowance"><label>Total model allowance ($)<input v-model="allowance.dollars" type="number" step="0.01" min="0" max="10" required></label><label>Total request limit<input v-model="allowance.attempts" type="number" min="1" max="250" required></label><button :disabled="busy">Review these limits</button> <button type="button" class="quiet" @click="editingAllowance = false; pilotReview = null">Cancel</button></form><div v-if="pilotReview" class="notice"><p>Approve {{ dollars(pilotReview.budgetMicros) }} cumulative model allowance and {{ pilotReview.maxProviderAttempts }} total attempts. {{ dollars(pilotReview.reservedMicros) }} already reserved stays counted. No automatic top-ups.</p><p>This also enables durable project progress as context for future requests. It does not send a model request or start coding.</p><button :disabled="busy" @click="approveAllowance">Approve pilot limits and memory</button></div></section>
      <section v-if="editingBrief" class="card">
        <h2>Update project brief</h2><p>Paste text or load a Markdown/text file. Chat messages do not replace this brief. The new brief is valid for seven days; old decisions remain in history. Old coding candidates are cleared. New assignments can be prepared from a plan.</p>
        <form @submit.prevent="previewBrief"><label>Project ID<input v-model="brief.id" pattern="[a-z0-9][a-z0-9-]{0,63}" required></label><label>Project name<input v-model="brief.name" maxlength="120" required></label><label>Objective<textarea v-model="brief.objective" maxlength="4000" required></textarea></label><label>Load a file<input type="file" accept=".md,.txt,text/plain,text/markdown" @change="loadBrief"></label><label>Project brief<textarea v-model="brief.text" rows="10" maxlength="4000" required></textarea></label><p class="muted">Preview saves a draft to your hosted workspace without calling a model. Approval allows the exact previewed brief to be sent to Eve and the configured model with future questions.</p><button :disabled="busy">Preview change</button> <button type="button" class="quiet" @click="editingBrief = false; contextPreview = null">Cancel</button></form>
        <div v-if="contextPreview" class="notice"><h3>Review the exact new context</h3><p>{{ contextPreview.previousProject.name }} ({{ contextPreview.previousProject.id }}) → {{ contextPreview.project.name }} ({{ contextPreview.project.id }})</p><p>{{ contextPreview.project.objective }}</p><pre>{{ contextPreview.project.sources[0].content }}</pre><p>Valid through {{ new Date(contextPreview.project.sources[0].expiresAt).toLocaleString() }}. {{ contextPreview.historicalCommitments }} commitments stay in history. Prior proposals cannot be approved against the new brief. {{ contextPreview.providerAttempts }} model attempts and {{ dollars(contextPreview.reservedMicros) }} reserved allowance are retained.</p><button :disabled="busy" @click="applyBrief">Approve this preview and use brief</button></div>
      </section>
      <section v-if="state.continuationAvailable || continuationReview" class="card"><h2>Continue with Eve</h2><p>The coding run is closed. Review one more Eve request using its verified result.</p><button v-if="!continuationReview" :disabled="busy" @click="reviewContinuation">Review next Eve request allowance</button><div v-else><p>Allow one additional request with {{ continuationReview.model }} ({{ continuationReview.previousLimit }} → {{ continuationReview.nextLimit }} total attempts). The cumulative ceiling stays {{ dollars(continuationReview.budgetMicros) }}; {{ dollars(continuationReview.reservedMicros) }} stays reserved. Provider admission will still require enough remaining allowance.</p><p>The recovered rejection stays in history with its evidence and reservation. Eve will receive this completion snapshot in addition to your approved brief. It cannot dispatch coding, merge or deploy from this approval.</p><details><summary>Review the completion snapshot sent to Eve</summary><pre>{{ continuationReview.source.content }}</pre></details><p>This approval expires {{ new Date(continuationReview.expiresAt).toLocaleString() }}.</p><button :disabled="busy" @click="continuePilot">Approve one more Eve request</button> <button class="quiet" :disabled="busy" @click="continuationReview = null">Cancel</button></div></section>
      <section id="coding-review" v-if="codingReview" class="card"><h2>Approve one coding assignment</h2><p>{{ codingReview.spec.objective }}</p><p>{{ codingReview.spec.acceptance }}</p><p>Repository: {{ codingReview.spec.repository }} ({{ codingReview.spec.visibility }}). Base: {{ codingReview.spec.baseBranch }} at {{ codingReview.spec.baseSha }}.</p><p>Allowed files: {{ codingReview.spec.allowedPaths.join(', ') }}</p><p>Required checks: {{ codingReview.spec.requiredChecks.map(c => c.name).join(', ') }}. Task branch: {{ codingReview.branch }}.</p><p>One Claude routine session may write that branch and open a draft PR. No merge, deployment or paid overage. Approval expires {{ new Date(codingReview.expiresAt).toLocaleString() }}.</p><p v-if="codingReview.followThrough">Eve may review this public PR up to 3 times and request up to 2 correction sessions within 24 hours, within the existing allowance. A confirmed end to the prior session is required before each correction. Repeated findings or uncertain delivery stop the loop.</p><button :disabled="busy" @click="dispatchCoding">Approve and start Claude</button> <button class="quiet" @click="codingReview = null">Cancel</button></section>
          <section class="card ask"><h2>What needs attention?</h2><p>Describe what you need. Eve uses your brief, saved notes, and recorded progress to propose the next useful step.</p><form @submit.prevent="propose"><label class="sr-only" for="request">Request to Eve</label><textarea id="request" v-model="message" maxlength="2000" rows="4" :disabled="busy || blocked" placeholder="We need to add the ability to…" required></textarea><button :disabled="busy || blocked || !message.trim()">{{ busy ? 'Working…' : 'Ask Eve' }}</button></form><p v-if="blocked" class="notice">{{ state.continuationProblem ? errors[state.continuationProblem] : state.paused ? 'New model requests are paused.' : state.providerAttempts >= state.maxProviderAttempts ? 'Your request allowance is used up. Review the pilot allowance to continue.' : !state.contextFresh ? 'The brief needs a fresh owner-approved update.' : 'A prior model attempt needs review. Its handoff under Decisions says what is known and who needs to act. Another attempt will not start automatically.' }}</p></section>
      <section id="assignment" v-if="assignmentOpen" class="card"><h2>Prepare a coding assignment</h2><p>Refine Eve’s plan into a bounded task. Steward supplies the approved repository, Claude connection, required checks, and current base revision.</p>
        <form @submit.prevent="prepareAssignment"><label>What should change?<textarea v-model="assignment.objective" maxlength="4000" required></textarea></label><label>What will count as done?<textarea v-model="assignment.acceptance" rows="4" maxlength="4000" required></textarea></label><label>Files Claude may change (one exact path per line)<textarea v-model="assignment.paths" rows="4" placeholder="integrations/eve/app/app.vue" required></textarea></label><p class="muted">Use 1–10 explicit files. A directory or wildcard does not grant scope. If the right files are unknown, inspect the project before approval.</p><button :disabled="busy">Prepare exact review</button> <button type="button" class="quiet" @click="assignmentOpen = false">Cancel</button></form>
      </section>
      <section v-if="state.codingJobs?.length" class="card"><h2>Coding progress</h2><article v-for="job in state.codingJobs" :key="job.id" class="coding-job"><div class="meta"><span class="tag">{{ jobStatus(job) }}</span></div><h3>{{ job.spec.objective }}</h3>
        <p v-if="job.result"><strong>{{ resultLabels[job.result.result] || 'Progress needs review' }}</strong><br><a v-if="job.result.prUrl" :href="job.result.prUrl" target="_blank" rel="noopener noreferrer">Open pull request</a><span class="muted"> · Checked {{ new Date(job.result.observedAt).toLocaleString() }}</span></p>
        <p v-if="job.stopRequested" class="notice">New work is paused. Check Claude directly to stop its session.</p>
        <div class="actions"><a v-if="job.session || job.receipt?.sessionUrlHint" :href="job.session?.url || job.receipt.sessionUrlHint" target="_blank" rel="noopener noreferrer">Open Claude</a><button class="quiet" :disabled="busy" @click="checkGitHub(job)">Check GitHub now</button><button v-if="!job.releasedAt && ['accepted', 'unknown'].includes(job.dispatch)" :disabled="busy" @click="observeJob(job)">Confirm Claude finished</button></div>
        <details><summary>Technical details</summary><p>Start receipt: {{ job.dispatch }}. Last observed Claude state: {{ job.execution }}. GitHub never proves that Claude has stopped.</p><p>Task marker: <code>{{ job.marker }}</code></p><p>Session: {{ job.session?.id || 'Not verified' }}</p></details>
      </article>
        <form v-if="observation.requestId" @submit.prevent="saveObservation" class="notice"><h3>Confirm this Claude session has ended</h3><p>Open Claude and check this is the task shown above. A draft PR alone does not mean the session ended.</p><label>Claude session link<input v-model="observation.sessionUrl" type="url" required></label><label>What does Claude show?<select v-model="observation.execution"><option value="exited">Finished</option><option value="stopped">Stopped</option></select></label><label class="checkbox"><input v-model="observation.markerVerified" type="checkbox" required>I checked the task marker and confirmed this session ended.</label><p>Steward will save your confirmation, check GitHub, and close the run. It will not merge or deploy.</p><button :disabled="busy">Save and close coding run</button> <button type="button" class="quiet" @click="observation.requestId = ''">Cancel</button></form>
      </section>
      <div class="columns">
        <div>

          <div id="decisions" class="section-title"><h2>Decisions · newest first</h2><button class="quiet" :disabled="busy" @click="action(refresh)">Refresh status</button></div>
          <p v-if="!state.requests.length" class="empty">Your first question starts the loop.</p>
          <template v-else><template v-for="group in decisionGroups" :key="group.key">
          <h3 class="group-heading">{{ group.heading }}</h3><p class="muted">{{ group.note }}</p>
          <p v-if="!group.records.length" class="empty">{{ group.empty }}</p>
          <article v-for="record in group.records" :key="record.id" class="card decision"><div class="meta"><span class="tag">{{ labels[record.status] || record.status }}</span><time>{{ new Date(record.createdAt).toLocaleString() }}</time></div><p class="request">{{ record.message }}</p><template v-if="record.proposal"><h3>{{ record.proposal.title }}</h3><p>{{ record.proposal.rationale }}</p><p v-if="record.proposal.question" class="notice">{{ record.proposal.question }}</p><p class="muted">Based on: {{ record.proposal.citations.join(', ') }}</p><button v-if="record.proposal.kind === 'plan' && record.status === 'awaiting_approval' && state.pilot && state.repeatableCoding && record.contextRevision === state.project.revision" class="quiet" :disabled="busy" @click="draftAssignment(record)">Turn this plan into an assignment</button><details v-if="record.proposal.kind === 'coding'"><summary>Proposed coding scope</summary><pre>{{ record.contextSnapshot.codingCandidates.find(c => c.id === record.proposal.candidateId)?.spec }}</pre></details><p v-if="record.contextRevision !== state.project.revision" class="notice">Historical context. This proposal cannot be approved for the current brief.</p><p v-if="record.proposal.kind === 'coding' && !state.codingEnabled" class="notice">Coding dispatch is not configured or its verification has expired.</p><button v-if="record.status === 'awaiting_approval' && record.proposal.kind === 'coding' && state.codingEnabled && record.contextRevision === state.project.revision" :disabled="busy || !state.contextFresh" @click="reviewCoding(record)">Review coding assignment</button><button v-if="record.status === 'awaiting_approval' && record.proposal.kind === 'commitment' && record.contextRevision === state.project.revision" :disabled="busy || !state.contextFresh" @click="approve(record)">Approve commitment</button></template><p v-else class="muted">{{ record.status === 'not_sent' ? 'The model was not contacted and no allowance was reserved. Check your remaining allowance and brief size, then submit a new request.' : record.status === 'resolved_rejection' ? 'A separate recovery succeeded. This failed attempt and its reservation remain in history; no further action is needed on this record.' : record.status === 'held' ? (record.purpose === 'coding_review' ? 'Eve did not return a verified review result. The attempt is held for operator review.' : 'Eve did not return a verified proposal. The attempt is held for operator review.') : record.status === 'rejection_acknowledged' ? 'The provider refused this automatic review. You acknowledged the failed attempt; it was not retried.' : 'The request was saved before contacting Eve. Refresh to check for a result.' }}</p><p v-if="record.provider?.httpStatus === 429" class="notice">The model gateway rejected this request (429). No automatic retry was sent.</p><p v-if="record.provider?.rejection?.providerErrors?.length" class="notice">Upstream response: {{ record.provider.rejection.providerErrors.map(e => `${e.provider} ${e.statusCode}${e.category === 'service_unavailable' ? ' (temporarily unavailable)' : ''}`).join(', ') }}.</p><div v-if="record.recovery" class="handoff" :data-recovery-case="record.recovery.case"><p class="eyebrow">{{ caseLabels[record.recovery.case] || record.recovery.case }}</p><dl><dt>What happened</dt><dd>{{ record.recovery.whatHappened }}</dd><dt>Still unknown</dt><dd>{{ record.recovery.unknown }}</dd><dt>Who needs to act</dt><dd>{{ record.recovery.whoActs }}</dd><template v-if="record.recovery.missing"><dt>Missing evidence or capability</dt><dd>{{ record.recovery.missing }}</dd></template><dt>Next step</dt><dd>{{ record.recovery.nextStep }}</dd></dl><button v-if="record.recovery.action === 'acknowledge'" :disabled="busy" @click="acknowledgeRecovery(record)">Acknowledge failed review</button></div><div v-if="record.status === 'rejection_acknowledged'" class="handoff" data-recovery-case="acknowledged"><p class="muted">Acknowledged {{ new Date(record.resolution.at).toLocaleString() }}. The failure record and its {{ micros(record.provider.reservedMicros) }} reservation stay in history. The old task grant was not resumed.</p><p><strong>Next step:</strong> start a fresh request. It gets a new request ID, and any coding work it proposes needs your fresh scope approval.</p><button v-if="!blocked" class="quiet" :disabled="busy" @click="startFresh">Start a fresh request</button><p v-else class="notice">A fresh request is not available yet; see the notice by the request form.</p></div><p v-if="record.retryRequestId" class="muted">A separate retry was requested. This failed attempt and its reservation remain recorded.</p><div v-else-if="record.retryReviewHash"><p class="muted">Retry this exact request once with {{ record.judge }} and the same brief. It uses the existing model allowance and does not start coding.</p><button class="quiet" :disabled="retryBlocked(record)" @click="retryRejected(record)">Retry this request once</button></div></article>
          </template></template>
        </div>
        <aside>
          <section class="card"><p class="eyebrow">DURABLE PROJECT MEMORY</p><h2>Progress and commitments</h2><p class="muted">Verified GitHub results and your dated updates carry into future Eve requests. Your notes are context, not execution approval.</p><form v-if="state.pilot" @submit.prevent="saveNote"><p v-if="state.progress?.priority"><strong>Current priority:</strong> {{ state.progress.priority.text }}</p><label>Type<select v-model="noteKind"><option value="note">Progress or decision</option><option value="priority">Current priority (kept until replaced)</option></select></label><label>Save an update for Eve<textarea v-model="note" rows="3" maxlength="1000" placeholder="Current priority, decision, or progress…" required></textarea></label><button class="quiet" :disabled="busy || !note.trim()">Save project note</button></form><details v-for="item in state.progress?.notes" :key="item.id"><summary>{{ new Date(item.at).toLocaleDateString() }} · Owner note</summary><p>{{ item.text }}</p></details>
          <div v-for="item in state.progress?.commitments || state.commitments" :key="item.id" class="commitment"><h3>{{ item.title }}</h3><p v-if="item.completedAt" class="muted">Completed · reported by you {{ new Date(item.completedAt).toLocaleDateString() }}</p><button v-else class="quiet" :disabled="busy" @click="complete(item)">Mark complete</button></div>
          <button v-if="state.pilot && state.repeatableCoding" class="quiet" :disabled="busy || !state.codingEnabled" @click="draftAssignment()">Prepare a coding assignment</button></section>
          <section class="card"><h2>Quiet follow-up</h2><p>GitHub checks run without using model allowance. Telegram updates are sent when a result changes. Claude completion still needs your confirmation.</p><p class="muted">{{ state.monitor?.lastCheckedAt ? `Last automatic check: ${new Date(state.monitor.lastCheckedAt).toLocaleString()}` : 'No automatic check recorded yet. The scheduler must be configured.' }}</p><p v-if="state.monitor?.lastError" class="notice">{{ state.monitor.lastError }}</p><p v-if="state.monitor?.notificationStatus" class="muted">{{ state.monitor.notificationStatus }}</p></section>
          <section class="card"><h2>Project brief</h2><button class="quiet" :disabled="busy" @click="editBrief">Update project brief</button><details v-for="source in state.project.sources" :key="source.id"><summary>{{ source.title }}</summary><p class="source">{{ source.content }}</p><p class="muted">Expires {{ new Date(source.expiresAt).toLocaleString() }}</p></details><p class="muted">Your approved brief, dated project progress, current commitments, and request are sent to Eve and the configured model.</p></section>
          <section class="card"><h2>Model allowance</h2><p class="allowance">{{ dollars(state.reservedMicros) }} <span>/ {{ dollars(state.budgetMicros) }}</span></p><p class="muted">{{ state.providerAttempts }} / {{ state.maxProviderAttempts }} pilot model attempts. Reserved allowance, not a bill. Uncertain attempts keep their reservation until reviewed.</p><button class="quiet" :disabled="busy" @click="editAllowance">Review pilot allowance</button> <button v-if="state.paused" class="quiet" :disabled="busy" @click="action(async () => { await api('steward/resume', {}); await refresh(); notice = 'New requests resumed.'; })">Resume requests</button> <button class="quiet" :disabled="busy || state.paused" @click="action(async () => { await api('steward/pause', {}); await refresh(); })">{{ state.paused ? 'Requests paused' : 'Pause new requests' }}</button></section>
        </aside>
      </div>
    </template>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <footer>Small steps. Clear decisions. Your approval.</footer>
  </main>
</template>
<style>
