nherit}input:focus,textarea:focus{outline:2px solid #779b7d;outline-offset:2px}textarea{resize:vertical;margin-bottom:14px}.heading{padding:34px 0}.heading h1{font-size:42px}.meta{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:12px;color:#6b786f}.columns{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr);gap:24px}.card{scroll-margin-top:90px;background:#fffefa;border:1px solid #dce1d5;border-radius:12px;padding:24px;margin-bottom:20px}.ask p{color:#6b786f}.section-title{display:flex;align-items:center;justify-content:space-between;margin:30px 0 18px}.section-title h2{margin:0}.request{border-bottom:1px solid #e5e7df;padding-bottom:15px;color:#6b786f}.notice,.error{background:#f8ecd3;color:#634d27;padding:12px 14px;border-radius:7px;font-size:13px}.error{position:sticky;bottom:16px;box-shadow:0 4px 24px #0001}.empty{padding:24px 0;color:#6b786f}.group-heading{margin:26px 0 4px;font-size:15px}.group-heading+.muted{margin:0 0 14px}.commitment+ .commitment{border-top:1px solid #e5e7df}.allowance{font:30px Georgia,serif}.allowance span{font-size:18px;color:#788579}details{border-bottom:1px solid #e5e7df;padding:13px 0;font-size:13px}summary{cursor:pointer;line-height:1.5}.source{white-space:pre-wrap}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}footer{padding:42px 0 14px;font-size:12px;color:#879285}.loading{padding:80px 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:700px){main{padding:20px}.columns{grid-template-columns:1fr}.card{padding:20px}.login{margin:45px auto}.heading h1{font-size:36px}.heading{padding:26px 0}.meta time{font-size:11px}}
select{font:inherit;padding:12px;border:1px solid #c5cfc3;border-radius:7px;background:white;color:inherit}form{display:grid;gap:12px}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0}.checkbox{display:flex;align-items:center;gap:10px;line-height:1.5}.checkbox input{width:18px;height:18px;flex:none}.coding-job+.coding-job{border-top:1px solid #e5e7df;padding-top:20px}.feedback{position:sticky;top:12px;z-index:2;box-shadow:0 4px 24px #0001}
